starter:
def dedupe_preserve_order(items):
    # remove duplicates but keep order
    pass

solution:
def dedupe_preserve_order(items):
    seen = set()
    result = []
    for item in items:
        if item not in seen:
            seen.add(item)
            result.append(item)
    return result

starter:
def group_by_first_letter(words):
    # build grouped dictionary
    pass

solution:
def group_by_first_letter(words):
    grouped = {}
    for word in words:
        if not word:
            continue
        key = word[0].lower()
        grouped.setdefault(key, []).append(word)
    return grouped

