    # use set operations and return sorted lists
    pass

solution:
def overlap_report(team_a, team_b):
    set_a = set(team_a)
    set_b = set(team_b)
    return {
        'common': sorted(set_a & set_b),
        'only_a': sorted(set_a - set_b),
        'only_b': sorted(set_b - set_a),
    }
